shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tests/unit/cluster/cluster-shards.tcl')
assert not path.exists()
path.write_text('''proc cluster_allocate_shards_test_slots {masters replicas} {
    R 0 CLUSTER ADDSLOTSRANGE 0 1000 1002 5460
    R 1 CLUSTER ADDSLOTSRANGE 5461 10922
    R 2 CLUSTER ADDSLOTSRANGE 1001 1001 10923 16383
}

proc cluster_shard_for_node {reference node_id} {
    foreach shard [R $reference CLUSTER SHARDS] {
        foreach node [dict get $shard nodes] {
            if {[dict get $node id] eq $node_id} {
                return $shard
            }
        }
    }
    fail "Node $node_id is missing from CLUSTER SHARDS on instance $reference"
}

start_cluster 3 3 {tags {external:skip cluster} overrides {cluster-replica-no-failover yes}} {
    set primary_id [R 0 CLUSTER MYID]
    set replica_id [R 3 CLUSTER MYID]
    set expected_slots {{0 1000 1002 5460} {5461 10922} {1001 1001 10923 16383}}
    set primary_ids [list $primary_id [R 1 CLUSTER MYID] [R 2 CLUSTER MYID]]

    test "CLUSTER SHARDS reports all slot ranges on primaries and replicas" {
        for {set reference 0} {$reference < 6} {incr reference} {
            assert_equal 3 [llength [R $reference CLUSTER SHARDS]]
            for {set shard 0} {$shard < 3} {incr shard} {
                set reply [cluster_shard_for_node $reference [lindex $primary_ids $shard]]
                assert_equal [lindex $expected_slots $shard] [dict get $reply slots]
                assert_equal 2 [llength [dict get $reply nodes]]
            }
        }
    }

    test "CLUSTER SHARDS retains slots for a failed primary before failover" {
        wait_for_sync [srv -3 client]
        pause_process [srv 0 pid]
        for {set reference 1} {$reference < 6} {incr reference} {
            wait_node_marked_fail $reference $primary_id
            assert_equal [lindex $expected_slots 0] [dict get [cluster_shard_for_node $reference $primary_id] slots]
        }
    }

    test "CLUSTER SHARDS reports slots after takeover while the old primary is down" {
        assert_equal OK [R 3 CLUSTER FAILOVER TAKEOVER]
        for {set reference 1} {$reference < 6} {incr reference} {
            wait_for_condition 1000 50 {
                [cluster_has_flag [cluster_get_node_by_id $reference $replica_id] master] &&
                [dict get [cluster_get_node_by_id $reference $primary_id] slots] eq {}
            } else {
                fail "Instance $reference did not learn the new slot owner"
            }
            # Both nodes still have the master role until the old primary returns.
            assert {[cluster_has_flag [cluster_get_node_by_id $reference $primary_id] master]}
            for {set repeat 0} {$repeat < 2} {incr repeat} {
                for {set shard 0} {$shard < 3} {incr shard} {
                    set reply [cluster_shard_for_node $reference [lindex $primary_ids $shard]]
                    assert_equal [lindex $expected_slots $shard] [dict get $reply slots]
                    assert_equal 2 [llength [dict get $reply nodes]]
                }
            }
        }
    }

    test "CLUSTER SHARDS retains slots after the old primary rejoins as a replica" {
        resume_process [srv 0 pid]
        wait_for_condition 1000 50 {
            [s 0 role] eq {slave}
        } else {
            fail "Old primary was not converted into a replica"
        }
        wait_for_cluster_propagation
        for {set reference 0} {$reference < 6} {incr reference} {
            assert_equal [lindex $expected_slots 0] [dict get [cluster_shard_for_node $reference $primary_id] slots]
        }
    }
} cluster_allocate_shards_test_slots

start_cluster 1 0 {tags {external:skip cluster}} {
    test "CLUSTER SHARDS returns empty slots only for a shard without slots" {
        R 0 CLUSTER DELSLOTSRANGE 0 16383
        set shards [R 0 CLUSTER SHARDS]
        assert_equal 1 [llength $shards]
        assert_equal {} [dict get [lindex $shards 0] slots]
        assert_equal 1 [llength [dict get [lindex $shards 0] nodes]]
    }
}
''')
PY
./runtest --single unit/cluster/cluster-shards

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('src/cluster_legacy.c')
source = path.read_text()
old = '''/* Add the shard reply of a single shard based off the given primary node. */
void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(listLength(nodes) > 0);
    clusterNode *n = listNodeValue(listFirst(nodes));
    addReplyMapLen(c, 2);
    addReplyBulkCString(c, "slots");

    /* Use slot_info_pairs from the primary only */
    n = clusterNodeGetPrimary(n);

    if (n->slot_info_pairs != NULL) {'''
new = '''/* Add the shard reply of a single shard based on its nodes. */
void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(listLength(nodes) > 0);
    clusterNode *n = NULL;
    listIter li;
    listRewind(nodes, &li);
    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
        clusterNode *node = listNodeValue(ln);
        /* A failed former primary may still have the primary role after failover. */
        if (node->slot_info_pairs != NULL) {
            n = node;
            break;
        }
    }

    addReplyMapLen(c, 2);
    addReplyBulkCString(c, "slots");
    if (n != NULL) {'''
assert source.count(old) == 1
source = source.replace(old, new)
old = '''    addReplyBulkCString(c, "nodes");
    addReplyArrayLen(c, listLength(nodes));
    listIter li;
    listRewind(nodes, &li);'''
new = '''    addReplyBulkCString(c, "nodes");
    addReplyArrayLen(c, listLength(nodes));
    listRewind(nodes, &li);'''
assert source.count(old) == 1
source = source.replace(old, new)
source = source.replace('/* If no slot info pair is provided, the node owns no slots */', '/* No node in the shard owns slots. */')
path.write_text(source)
path = Path('src/commands/cluster-shards.json')
source = path.read_text()
old = 'An even number element array specifying the start and end slot numbers for slot ranges owned by this shard.'
new = old + ' The array is empty only if no node in the shard owns slots.'
assert source.count(old) == 1
path.write_text(source.replace(old, new))
PY
make -j4 > /tmp/valkey-cluster-shards-build.log 2>&1 && tail -8 /tmp/valkey-cluster-shards-build.log

